<?php session_start(); require_once __DIR__.'/../config/database.php'; require_role('student'); $data=db_load(); $student=db_student_by_user($data,(int)$_SESSION['user_id']); $sid=(int)($student['id']??0); $rows=[]; foreach($data['applications'] as $a){if((int)$a['student_id']!==$sid)continue;$i=db_internship($data,(int)$a['internship_id']);if(!$i)continue;$c=db_company($data,(int)$i['company_id']);$a['title']=$i['title'];$a['company_name']=$c['company_name']??'Unknown';$rows[]=$a;} usort($rows,fn($a,$b)=>strcmp($b['applied_at'],$a['applied_at'])); ?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Applications · Arti Vaniyar Internships Hub</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include 'student_nav.php'; ?><main class="dashboard"><div class="page-heading"><div><p class="eyebrow">APPLICATION TRACKER</p><h1>My applications</h1><p>Keep an eye on every opportunity you applied for.</p></div></div><div class="table-card"><table><thead><tr><th>Internship</th><th>Company</th><th>Applied</th><th>Status</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="4" class="empty">No applications yet. <a href="internships.php" style="color:#22d3ee">Browse internships →</a></td></tr><?php else: foreach($rows as $r): ?><tr><td><strong><?=e($r['title'])?></strong></td><td><?=e($r['company_name'])?></td><td><?=e(date('d M Y',strtotime($r['applied_at'])))?></td><td><span class="status <?=e(status_class($r['status']))?>"><?=e($r['status'])?></span></td></tr><?php endforeach; endif; ?></tbody></table></div></main></body></html>
